using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Saldo360.Domain.Accounts;
using Saldo360.Domain.Debts;
using Saldo360.Domain.Families;
namespace Saldo360.Infrastructure.Persistence.Configurations;
internal sealed class FinancialDebtConfiguration:IEntityTypeConfiguration<FinancialDebt>
{
 public void Configure(EntityTypeBuilder<FinancialDebt> b){b.ToTable("financial_debts",t=>{t.HasCheckConstraint("ck_debts_original_principal","original_principal > 0");t.HasCheckConstraint("ck_debts_nonnegative","(outstanding_principal IS NULL OR outstanding_principal >= 0) AND (outstanding_balance IS NULL OR outstanding_balance >= 0) AND (installment_amount IS NULL OR installment_amount >= 0) AND (interest_rate IS NULL OR interest_rate >= 0)");t.HasCheckConstraint("ck_debts_installments","(installment_count IS NULL OR installment_count > 0) AND (paid_installment_count IS NULL OR paid_installment_count >= 0) AND (paid_installment_count IS NULL OR installment_count IS NULL OR paid_installment_count <= installment_count)");t.HasCheckConstraint("ck_debts_reference","(balance_reference_date IS NULL OR outstanding_balance IS NOT NULL)");t.HasCheckConstraint("ck_debts_archived","(status = 3) = (archived_at IS NOT NULL)");});b.HasKey(x=>x.Id);b.Property(x=>x.Id).ValueGeneratedNever();b.Property(x=>x.Name).HasMaxLength(FinancialDebt.NameMaxLength).IsRequired();b.Property(x=>x.Description).HasMaxLength(FinancialDebt.DescriptionMaxLength);b.Property(x=>x.LenderName).HasMaxLength(FinancialDebt.LenderNameMaxLength);b.Property(x=>x.OriginalPrincipal).HasPrecision(18,2);b.Property(x=>x.OutstandingPrincipal).HasPrecision(18,2);b.Property(x=>x.OutstandingBalance).HasPrecision(18,2);b.Property(x=>x.InstallmentAmount).HasPrecision(18,2);b.Property(x=>x.InterestRate).HasPrecision(9,4);b.Property(x=>x.DebtType).HasConversion<int>();b.Property(x=>x.Status).HasConversion<int>();b.Property(x=>x.InterestRatePeriod).HasConversion<int>();b.Property(x=>x.AmortizationMethod).HasConversion<int>();b.Property(x=>x.ContractDate).HasColumnType("date");b.Property(x=>x.FirstDueDate).HasColumnType("date");b.Property(x=>x.BalanceReferenceDate).HasColumnType("date");b.HasAlternateKey(x=>new{x.FamilyId,x.Id});b.HasIndex(x=>new{x.FamilyId,x.Status});b.HasOne<Family>().WithMany().HasForeignKey(x=>x.FamilyId).OnDelete(DeleteBehavior.Restrict);b.HasOne<FinancialAccount>().WithMany().HasForeignKey(x=>new{x.FamilyId,x.ResponsibleAccountId}).HasPrincipalKey(x=>new{x.FamilyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}
}
